<?php
namespace App\Http\Controllers;
use App\Models\Category;
use App\Models\Product;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Storage;
use Illuminate\Validation\Rule;
class ProductController extends Controller {
 private function businessId():int{$id=auth()->user()->mype_id;abort_unless($id,403,'No tienes una empresa asignada.');return (int)$id;}
 public function index(Request $request){$id=$this->businessId();$base=Product::where('mype_id',$id);$products=(clone $base)->with('category')->when($request->filled('search'),function($q)use($request){$term=$request->input('search');$q->where(fn($sub)=>$sub->where('name','like',"%{$term}%")->orWhere('sku','like',"%{$term}%"));})->latest()->paginate(10)->withQueryString();$categories=Category::where('mype_id',$id)->where('active',true)->orderBy('name')->get();$totalProducts=(clone $base)->count();$activeProducts=(clone $base)->where('active',true)->where('stock','>',0)->count();$outOfStock=(clone $base)->where('stock',0)->count();return view('products.index',compact('products','categories','totalProducts','activeProducts','outOfStock'));}
 private function rules(int $id,?Product $product=null):array{return ['name'=>['required','string','max:180'],'sku'=>['required','string','max:80',Rule::unique('products','sku')->where('mype_id',$id)->ignore($product?->id)],'category_id'=>['required','integer',Rule::exists('categories','id')->where('mype_id',$id)],'description'=>['nullable','string'],'purchase_price'=>['required','numeric','min:0'],'sale_price'=>['required','numeric','min:0'],'stock'=>['required','integer','min:0'],'active'=>['nullable','boolean'],'image'=>['nullable','image','max:5120']];}
 public function store(Request $request){$id=$this->businessId();$data=$request->validate($this->rules($id));$data['mype_id']=$id;$data['active']=$request->boolean('active');if($request->hasFile('image'))$data['image']=$request->file('image')->store('products','public');try{Product::create($data);}catch(\Throwable $e){if(!empty($data['image']))Storage::disk('public')->delete($data['image']);throw $e;}return redirect()->route('products.index')->with('success','Producto registrado correctamente.');}
 public function update(Request $request,Product $product){$id=$this->businessId();abort_unless((int)$product->mype_id===$id,404);$data=$request->validate($this->rules($id,$product));$data['active']=$request->boolean('active');$newImage=null;$oldImage=$product->image;if($request->hasFile('image')){$newImage=$request->file('image')->store('products','public');$data['image']=$newImage;}try{$product->update($data);}catch(\Throwable $e){if($newImage)Storage::disk('public')->delete($newImage);throw $e;}if($newImage&&$oldImage)Storage::disk('public')->delete($oldImage);return back()->with('success','Producto actualizado.');}
 public function destroy(Product $product){abort_unless((int)$product->mype_id===$this->businessId(),404);if(\Illuminate\Support\Facades\Schema::hasTable('order_items') && \Illuminate\Support\Facades\DB::table('order_items')->where('product_id',$product->id)->exists())return back()->with('error','Este producto tiene pedidos asociados y no puede eliminarse.');$image=$product->image;$product->delete();if($image)Storage::disk('public')->delete($image);return back()->with('success','Producto eliminado.');}
}
